import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import os from 'node:os';import path from 'node:path';import {execFileSync} from 'node:child_process';
import {harness,item,extract} from './pno-rev89-contract-harness.mjs';
const records=[item('NQR-A','B1','NE11','(TH001) สาขาไทย'),item('NQR-B','B1','E1','OTHER-R','เข้าแล้ว','SHIPMENT_WAREHOUSE_SCAN')];
for(const type of ['bag','total','already','no_entry','scan_gap'])test(type+' Copy/LINE/XLSX preserve independent raw N, Q, R after complete acceptance',async()=>{
 const rows=records.map(r=>({...r,scanEvidence:{classification:'INSUFFICIENT_HISTORY',reason:'SYNTHETIC_ONLY'}}));const h=harness(rows);h.state.type=type;h.state.rows=rows;h.state.filterRows=type==='bag'?null:rows;h.state.filters.hub='NE11';
 await h.call('pnoV18Copy()');assert.ok(h.obs.clip.includes('NE11'));assert.ok(h.obs.clip.includes('สาขาไทย'));assert.ok(h.obs.clip.includes('NEXT_ONLY'));assert.ok(!h.obs.clip.includes('OTHER-R'));
 await h.call('pnoV18CopyLine()');assert.ok(h.obs.clip.includes('NE11'));assert.ok(h.obs.clip.includes('สาขาไทย'));assert.ok(h.obs.clip.includes('ชื่อสาขาต่อไป: NEXT_ONLY'));assert.ok(!h.obs.clip.includes('OTHER-R'));
 await h.call('pnoV18Export()');assert.equal(h.obs.exports.length,1);assert.equal(h.obs.exports[0]['HUB ปลายทาง'],'NE11');assert.equal(h.obs.exports[0]['ชื่อสาขาต่อไป'],'NEXT_ONLY');assert.ok(h.obs.exports[0]['สาขาปลายทาง'].includes('สาขาไทย'));assert.equal(h.obs.fetch.length,0);
 if(type==='no_entry'||type==='scan_gap')assert.ok(!h.obs.clip.includes('ยืนยันสแกนเข้าคลังแล้ว'),'metadata projection cannot fabricate scan confirmation');
});
test('tab transition clears FOUR selected values and filter page, only new view acquires',async()=>{const h=harness(records);h.state.type='total';Object.assign(h.state.filters,{status:'รอ',action:'ปิดผนึก',hub:'NE11',branch:'(TH001) สาขาไทย'});h.state.filterPage=4;await h.call('pnoV18LoadBags()');assert.deepEqual(h.state.filters,{status:'',action:'',hub:'',branch:''});assert.equal(h.state.filterPage,1);assert.deepEqual(h.obs.fetch,[1]);});
test('same-tab cache reopening retains all selected values and complete option universe',async()=>{const h=harness(records);await h.call('pnoV18LoadBags()');Object.assign(h.state.filters,{status:'รอ',action:'ปิดผนึก',hub:'NE11',branch:'(TH001) สาขาไทย'});await h.call('pnoV18LoadBags()');assert.deepEqual(h.state.filters,{status:'รอ',action:'ปิดผนึก',hub:'NE11',branch:'(TH001) สาขาไทย'});assert.ok(h.node('pno-v18-filterbar').innerHTML.includes('E1'));assert.deepEqual(h.obs.fetch,[1]);});
test('HUB invalidates only its incompatible child; zero-match retains unrelated values/options',()=>{const h=harness(records);Object.assign(h.state.filters,{status:'NO-MATCH',action:'ปิดผนึก',hub:'E1',branch:'(TH001) สาขาไทย'});h.call('pnoV18RenderFilters()');assert.equal(h.state.filters.branch,'');assert.equal(h.state.filters.status,'NO-MATCH');assert.equal(h.state.filters.action,'ปิดผนึก');assert.equal(h.call('pnoV18FilteredBagGroups().length'),0);const html=h.node('pno-v18-filterbar').innerHTML;for(const value of ['NE11','E1','OTHER-R','NO-MATCH'])assert.ok(html.includes(value));assert.equal(h.obs.fetch.length,0);});
test('explicit RESET clears all values locally',()=>{const h=harness(records);Object.assign(h.state.filters,{status:'รอ',action:'ปิดผนึก',hub:'NE11',branch:'(TH001) สาขาไทย'});h.call('pnoV18RenderFilters()');h.node('pno-v18-filter-reset').onclick();assert.deepEqual(h.state.filters,{status:'',action:'',hub:'',branch:''});assert.equal(h.obs.fetch.length,0);});
test('cached authority cannot cross day, line, selected HUB or segment identity',async()=>{for(const change of [h=>{h.state.sourceRow.pnoSourceDay='2026-10-14';},h=>{h.state.sourceRow.pnoLineId='OTHER';},h=>{h.context.state.branch='E1';},h=>{h.state.segmentSignature='OTHER-SEGMENT';}]){const h=harness(records);await h.call('pnoV18LoadBags()');change(h);await h.call('pnoV18LoadBags()');assert.deepEqual(h.obs.fetch,[1,1]);assert.equal(h.state.filterError,'');}});
test('missing Next Store remains unknown in every representation; no Q/R fallback',async()=>{const h=harness([{...item('UNKNOWN-N','B','NE11','R'),nextStoreName:''}]);await h.call('pnoV18Copy()');assert.equal(h.obs.clip.split('\n')[1].split('\t')[6],'-');await h.call('pnoV18Export()');assert.equal(h.obs.exports[0]['ชื่อสาขาต่อไป'],'-');h.state.type='total';h.state.rows=h.state.bagRows;h.state.filterRows=h.state.rows;await h.call('pnoV18Copy()');assert.equal(h.obs.clip.split('\n')[1].split('\t')[6],'');await h.call('pnoV18Export()');assert.equal(h.obs.exports[0]['ชื่อสาขาต่อไป'],'');});
test('whole raw R identity survives grouping even when cosmetic labels agree',()=>{const h=harness([item('RAW-A','B','NE11','(TH001)ชื่อเดียว'),item('RAW-B','B','NE11','(TH002)ชื่อเดียว')]);h.state.filters.branch='(TH001)ชื่อเดียว';assert.deepEqual(JSON.parse(JSON.stringify(h.call('pnoV18FilteredBagGroups()[0][1].map(x=>x.pno)'))),['RAW-A']);});
test('unknown or overlapping source identities still fail closed before acceptance',async()=>{for(const rows of [[{...records[0],pno:''}],[records[0],{...records[0]}],[records[0],{...records[0],occurrence:'OTHER'}]]){const h=harness(rows);await h.call('pnoV18LoadBags()');assert.equal(h.state.bagRows,null);assert.ok(h.state.filterError);assert.equal(h.obs.cache,0);}});
test('candidate functions match full CLI-composed frontend, not canonical-only assumptions',()=>{
 const root=path.resolve(import.meta.dirname,'../..'),temp=fs.mkdtempSync(path.join(os.tmpdir(),'rev89-compose-'));
 try {
  for(const name of fs.readdirSync(root))if(/\.(?:html|js|css|svg)$/.test(name))fs.copyFileSync(path.join(root,name),path.join(temp,name));
  fs.cpSync(path.join(root,'worker/src'),path.join(temp,'src'),{recursive:true});
  execFileSync(process.execPath,[path.join(root,'.github/dev-tools/stage-dev-runtime.mjs'),path.join(temp,'ms.js'),path.join(temp,'src/index.js')],{stdio:'pipe'});
  execFileSync(process.execPath,[path.join(root,'.github/dev-tools/patch-dev-origin-manifest-session-v2.mjs'),path.join(temp,'ms.js'),path.join(temp,'src/origin-manifest-v1.js')],{stdio:'pipe'});
  const source=fs.readFileSync(path.join(root,'ms.js'),'utf8'),full=fs.readFileSync(path.join(temp,'ms.js'),'utf8');
  assert.ok(!source.includes('PNO_BAG_MEMBER_FILTER_PARITY_REV86'));
  for(const n of ['pnoV18Copy','pnoV18CopyLine','pnoV18Export','pnoV18LoadBags']){const h=harness(records);assert.equal(h.context[n].toString().replace(/^async /,''),extract(full,n).replace(/^async /,''));}
 } finally {fs.rmSync(temp,{recursive:true,force:true});}
});
